-- Symmetric window for the interval criterion: W = [(1-a)U, (1+a)U] with the kernel peak k/c at U, k = ceil(cU).
-- 8JT4 (ii) now holds for every 0<a<1 with the explicit choice lambda = a/2, and its tails are one-step chains.
-- The criterion (8JP5, 8JT2, KW4N; zeta: 8JUP, 8JUQ) takes the hypothesis on [Y^{1-a}, Y^{1+a}] for some 0<a<1.
-- 8JK2 keeps [Y, Y^{3/2}] = [Y'^{4/5}, Y'^{6/5}] with Y' = Y^{5/4}, i.e. a = 1/5; 8JR6 and 8JTA say so.
-- 8JT7 shows the rescaled kernels for a = 1/5 (figure regenerated by scripts/plot-gamma-kernel.mjs).

INSERT OR ROLLBACK INTO write_guard (ok)
SELECT 0 WHERE
  NOT EXISTS (SELECT 1 FROM results WHERE id IS 113 AND tag IS '8JP5' AND revision IS 2)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 123 AND tag IS '8JT2' AND revision IS 6)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 125 AND tag IS '8JT4' AND revision IS 4)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 138 AND tag IS '8JT7' AND revision IS 2)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 146 AND tag IS '8JUP' AND revision IS 2)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 147 AND tag IS '8JUQ' AND revision IS 1)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 198 AND tag IS 'KW4N' AND revision IS 2)
  OR NOT EXISTS (SELECT 1 FROM results WHERE id IS 141 AND tag IS '8JTA' AND revision IS 9
    AND instr(statement_tex, 'on sparse intervals $[Y, Y^{3/2}]$. The \hyperref[8JUQ]{zeta interval criterion}, applied with $\theta=1/2+\varepsilon$ for every') > 0)
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id IS 109 AND revision IS 16)
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id IS 111 AND revision IS 5)
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id IS 126 AND revision IS 4)
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id IS 158 AND revision IS 1)
  OR NOT EXISTS (SELECT 1 FROM proofs WHERE id IS 103 AND revision IS 2
    AND instr(body_tex, 'The \hyperref[8JK2]{interval estimate} with $\varepsilon = \theta - \frac12$ is the hypothesis of the \hyperref[8JP5]{interval criterion} for this $\theta$.') > 0);

-- 8JT4: concentration of the kernel.
UPDATE results SET statement_tex =
'For real $c > 2$ and integers $k \ge 0$ let $K_k(u) = u^k e^{-cu}/k!$ for $u \ge 0$.
\begin{enumerate}
\item[(i)] For every real $\sigma < c$, $\displaystyle\int_0^\infty e^{\sigma u} K_k(u)\,du = (c - \sigma)^{-k-1}$.
\item[(ii)] For every real $0 < a < 1$ there is a real $c_* > 2$ such that the following holds for every real $c \ge c_*$ and every real $U > 0$. Put $W = [(1-a)U, (1+a)U]$ and $k = \lceil cU \rceil$. Then
\[ \int_{u \notin W} e^{2u} K_k(u)\,du \le 2c^{-k}. \]
\end{enumerate}
See the \hyperref[8JT6]{graphs of $K_k$} and \hyperref[8JT7]{how $K_k$ concentrates in $W$}.',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 125;

UPDATE proofs SET body_tex =
'\emph{(i)} \textbf{This is a Gamma integral.} Substitute $v = (c - \sigma)u$ in $\int_0^\infty u^k e^{-(c - \sigma)u}\,du$ and use $\int_0^\infty v^k e^{-v}\,dv = k!$.

\emph{(ii)} \textbf{$W$ reaches the fraction $a$ beyond the peak of $K_k$ on each side; outside $W$, bound $1$ by an exponential and integrate over all $u$ with (i).} The kernel $K_k$ peaks at $u=k/c$, and the choice of $k$ gives $k-1<cU\le k$, so the peak lies in $[U,U+1/c)$. Put
\[ \lambda=\frac a2,\qquad t=\lambda c. \]
Then $tU=\lambda cU$, so $\lambda(k-1)\le tU\le\lambda k$.

\emph{Right of $W$.}
\begin{alignat*}{2}
\int_{u>(1+a)U}e^{2u}K_k(u)\,du
&\le \int_{u>(1+a)U}e^{2u}\,e^{t(u-(1+a)U)}K_k(u)\,du &\qquad& \text{(a)}\\
&\le e^{-t(1+a)U}\int_0^\infty e^{(2+t)u}K_k(u)\,du && \text{(b)}\\
&= e^{-t(1+a)U}\,(c-2-t)^{-k-1} && \text{(c)}\\
&\le e^{-\lambda(1+a)(k-1)}\,(c-2-t)^{-k-1} && \text{(d)}\\
&= c^{-k}\cdot\frac{e^{\lambda(1+a)}}{c\,(1-\lambda-2/c)}\cdot\biggl(\frac{e^{-\lambda(1+a)}}{1-\lambda-2/c}\biggr)^{k}. && \text{(e)}
\end{alignat*}

\emph{Left of $W$.}
\begin{alignat*}{2}
\int_{u<(1-a)U}e^{2u}K_k(u)\,du
&\le \int_{u<(1-a)U}e^{2u}\,e^{t((1-a)U-u)}K_k(u)\,du &\qquad& \text{(a)}\\
&\le e^{t(1-a)U}\int_0^\infty e^{(2-t)u}K_k(u)\,du && \text{(b)}\\
&= e^{t(1-a)U}\,(c-2+t)^{-k-1} && \text{(c)}\\
&\le e^{\lambda(1-a)k}\,(c-2+t)^{-k-1} && \text{(d)}\\
&= c^{-k}\cdot\frac{1}{c\,(1+\lambda-2/c)}\cdot\biggl(\frac{e^{\lambda(1-a)}}{1+\lambda-2/c}\biggr)^{k}. && \text{(e)}
\end{alignat*}
In both chains:
\begin{itemize}
\item[(a)] the inserted exponential is at least $1$ on the range of integration;
\item[(b)] the integrand is nonnegative, so the integral may be extended to all $u\ge0$;
\item[(c)] part (i), with $\sigma=2+t$ on the right and $\sigma=2-t$ on the left; $2+t<c$ holds by the choice of $c_*$ below;
\item[(d)] $tU\ge\lambda(k-1)$ on the right, and $tU\le\lambda k$ on the left;
\item[(e)] $c-2\mp t=c\,(1\mp\lambda-2/c)$.
\end{itemize}

\emph{The limits of the bases are less than $1$.} As $c\to\infty$, the bases of the $k$-th powers tend to $e^{-\lambda(1+a)}/(1-\lambda)$ and $e^{\lambda(1-a)}/(1+\lambda)$. Since $a=2\lambda$ and $0<\lambda<\frac12$, the series of the logarithm gives
\begin{align*}
-\ln(1-\lambda)&\le\lambda+\frac{\lambda^2}{2(1-\lambda)}<\lambda+\lambda^2<\lambda(1+a),\\
\ln(1+\lambda)&\ge\lambda-\frac{\lambda^2}{2}>\lambda-2\lambda^2=\lambda(1-a),
\end{align*}
so both limits are less than $1$.

\emph{Choice of $c_*$.} The middle factors tend to $0$ as $c\to\infty$. Take $c_*$ so large that for every $c\ge c_*$ we have $2+t<c$, and both bases and both middle factors are at most $1$. Then each tail is at most $c^{-k}$, which gives (ii).',
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 111;

-- KW4N: kernel bound on and off the window.
UPDATE results SET statement_tex =
'Let $0<a<1$ be real, let $c_*$ be as in the \hyperref[8JT4]{concentration of the kernel} for this $a$, and let $c\ge c_*$, $0<\theta<1$ and $U>0$ be real. Put
\[
W=[(1-a)U,(1+a)U],\qquad k=\lceil cU\rceil,\qquad K_k(u)=\frac{u^ke^{-cu}}{k!}\quad(u\ge0).
\]
\begin{enumerate}
\item[(i)] $\displaystyle\int_W e^{\theta u}K_k(u)\,du\le(c-\theta)^{-k-1}$.
\item[(ii)] $\displaystyle\int_{[0,\infty)\setminus W}e^{2u}K_k(u)\,du\le2c^{-k}$.
\end{enumerate}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 198;
UPDATE proofs SET body_tex = replace(body_tex, '(i) with $a=\theta<c$', '(i) with $\sigma=\theta<c$'),
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 158;

-- 8JT2: one-sided bound for the Taylor coefficients.
UPDATE results SET statement_tex =
'Let $\psi$ be a primitive character, $0 < \theta < 1$ and $0 < a < 1$. Suppose that for every $Y_0 \ge 1$ there is $Y \ge Y_0$ with
\[ \mathcal G_\psi(x) \le x^\theta \qquad \text{for all } x \in [Y^{1-a}, Y^{1+a}]. \]
Let $A_k$ be the \hyperref[TQ4B]{Taylor coefficients} of $\mathcal H_\psi$. Then there is $c_0 > 2$ such that for every real $c \ge c_0$ there are a constant $C > 0$ and an infinite set $K$ of positive integers with
\[ \text{for all } k \in K \text{ and all } y \in \R: \qquad |A_k(c+iy)| + \Re A_k(c) \le C\,(c-\theta)^{-k}. \]',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 123;

UPDATE proofs SET body_tex = replace(body_tex,
'Let $c_0 = c_*$, as in the \hyperref[8JT4]{concentration of the kernel}, and fix a real $c \ge c_0$. For each $Y \ge 2$ given by the hypothesis put $U = \ln Y$ and
\[ W = [U, \tfrac32 U], \qquad k = \bigl\lceil \tfrac54 c U \bigr\rceil, \qquad K_k(u) = \frac{u^k e^{-cu}}{k!}. \]
Here $W$ is the window $Y \le x \le Y^{3/2}$ in the variable $u = \ln x$, and $k$ puts the peak $u = k/c$ of $K_k$ (see the \hyperref[8JT6]{graphs of $K_k$}) at the midpoint $\frac54 U$ of $W$, up to rounding.',
'Let $c_0 = c_*$ be as in the \hyperref[8JT4]{concentration of the kernel} for this $a$, and fix a real $c \ge c_0$. For each $Y \ge 2$ given by the hypothesis put $U = \ln Y$ and
\[ W = [(1-a)U, (1+a)U], \qquad k = \lceil cU \rceil, \qquad K_k(u) = \frac{u^k e^{-cu}}{k!}. \]
Here $W$ is the window $Y^{1-a} \le x \le Y^{1+a}$ in the variable $u = \ln x$, and $k$ puts the peak $u = k/c$ of $K_k$ (see the \hyperref[8JT6]{graphs of $K_k$}) at the centre $U$ of $W$, up to rounding.'),
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 109 AND instr(body_tex, 'at the midpoint $\frac54 U$ of $W$, up to rounding.') > 0;

-- 8JP5: interval criterion.
UPDATE results SET statement_tex =
'Let $0 < \theta < 1$ and $0 < a < 1$, and suppose that, for arbitrarily large $Y$,
\[ \mathcal G_\psi(x) \le x^\theta \qquad (Y^{1-a} \le x \le Y^{1+a}). \]
Then, with $Z$ the \hyperref[8JN4]{set of poles} of $\mathcal H_\psi$,
\[ \Re\rho \le \theta \qquad \text{for every } \rho \in Z. \]',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 113;

-- 8JR6: the interval estimate is the case a = 1/5.
UPDATE proofs SET body_tex = replace(body_tex,
'The \hyperref[8JK2]{interval estimate} with $\varepsilon = \theta - \frac12$ is the hypothesis of the \hyperref[8JP5]{interval criterion} for this $\theta$.',
'The \hyperref[8JK2]{interval estimate} with $\varepsilon = \theta - \frac12$ gives $\mathcal G_\psi(x) \le x^\theta$ for $x$ in $[Y, Y^{3/2}] = [Y''^{4/5}, Y''^{6/5}]$, with $Y'' = Y^{5/4}$ arbitrarily large. This is the hypothesis of the \hyperref[8JP5]{interval criterion} for this $\theta$ and $a = \frac15$.'),
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 103;

-- 8JT7: the kernels concentrate in W (a = 1/5).
UPDATE results SET statement_tex =
'Let $0 < a < 1$, $U > 0$ and $W = [(1-a)U, (1+a)U]$, and let $c > 0$ and a positive integer $k$ satisfy $k/c = U$, so that the kernel $K_k(u) = u^k e^{-cu}/k!$ peaks at the centre of $W$, as in the \hyperref[8JT2]{one-sided bound} up to rounding. Rescaled to peak value $1$, the kernel is
\[ \frac{K_k(u)}{K_k(k/c)} = \Bigl(\frac{cu}{k}\Bigr)^{k} e^{k - cu}, \]
which depends only on $k$ and $u/U$. The graphs show it for $k = 3, 30, 300$ and $a = \frac15$, the window that the \hyperref[8JK2]{interval estimate} provides, with $W$ shaded. As $k$ grows, the kernel concentrates in $W$; part (ii) of the \hyperref[8JT4]{concentration of the kernel} is a quantitative version of this.
\includegraphics[width=1, alt=Rescaled kernels for k = 3, 30, 300 peaking at U, the centre of the shaded interval W = [4U/5, 6U/5]]{/static/figures/gamma-kernel-b.svg}',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 138;

-- 8JUP: one-sided bound for H_1.
UPDATE results SET statement_tex =
'Let $0<\theta<1$ and $0<a<1$. Suppose that for every real $Y_0\ge 1$ there is a real $Y\ge Y_0$ such that
$$
G_{\mathbf 1}(x)\le x^\theta
\qquad \text{for every } x\in[Y^{1-a},Y^{1+a}].
$$
Let $A_k$ be the Taylor coefficients of $H_{\mathbf 1}$ in the \hyperref[8JTA]{zeta example}. There is a real $c_0>2$ such that for every real $c\ge c_0$ there are a constant $C>0$ and an infinite set $K$ of positive integers with the following property. For every $k\in K$ and every real $y$,
$$
|A_k(c+iy)|+\Re A_k(c)\le C(c-\theta)^{-k}.
$$',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 146;

UPDATE proofs SET body_tex = replace(body_tex,
'Put $c_0=c_*$, the threshold in the \hyperref[8JT4]{kernel concentration estimate}, and fix $c\ge c_0$. For each $Y>1$ in the hypothesis put $U=\ln Y$ and choose
$$
W=[U,\tfrac32 U],\qquad k=\bigl\lceil\tfrac54c U\bigr\rceil,
\qquad K_k(u)=\frac{u^k e^{-cu}}{k!}.
$$
This puts the peak of $K_k$ at the midpoint of $W$, up to rounding.',
'Put $c_0=c_*$, the threshold in the \hyperref[8JT4]{kernel concentration estimate} for this $a$, and fix $c\ge c_0$. For each $Y>1$ in the hypothesis put $U=\ln Y$ and choose
$$
W=[(1-a)U,(1+a)U],\qquad k=\lceil cU\rceil,
\qquad K_k(u)=\frac{u^k e^{-cu}}{k!}.
$$
This puts the peak of $K_k$ at the centre $U$ of $W$, up to rounding.'),
  body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 126 AND instr(body_tex, 'This puts the peak of $K_k$ at the midpoint of $W$, up to rounding.') > 0;

-- 8JUQ: interval criterion for zeta.
UPDATE results SET statement_tex =
'Let $0<\theta<1$ and $0<a<1$. Suppose that for every real $Y_0\ge 1$ there is a real $Y\ge Y_0$ such that $G_{\mathbf 1}(x)\le x^\theta$ for every $x\in[Y^{1-a},Y^{1+a}]$. Then every nontrivial zero $\rho$ of $\zeta$ satisfies $\Re\rho\le\theta$.',
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 147;

-- 8JTA: the zeta criterion is applied with a = 1/5.
UPDATE results SET statement_tex = replace(statement_tex,
'on sparse intervals $[Y, Y^{3/2}]$. The \hyperref[8JUQ]{zeta interval criterion}, applied with $\theta=1/2+\varepsilon$ for every',
'on sparse intervals $[Y, Y^{3/2}]$, which are $[Y''^{4/5}, Y''^{6/5}]$ with $Y'' = Y^{5/4}$. The \hyperref[8JUQ]{zeta interval criterion}, applied with $a=\frac15$ and $\theta=1/2+\varepsilon$ for every'),
  statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-27 21:00:00', updated_by = 'claude'
WHERE id = 141;
